// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/advisories", wrapper.ListAdvisories)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/advisories", wrapper.CreateAdvisory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/advisories/preview", wrapper.PreviewAdvisoryRecipients)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/advisories/{advisory_id}", wrapper.GetAdvisory)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/admin/advisories/{advisory_id}", wrapper.UpdateAdvisory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/advisories/{advisory_id}/submit", wrapper.SubmitAdvisory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/advisories/{advisory_id}/approve", wrapper.ApproveAdvisory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/advisories/{advisory_id}/reject", wrapper.RejectAdvisory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/advisories/{advisory_id}/cancel", wrapper.CancelAdvisory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/advisories/{advisory_id}/recipients", wrapper.ListAdvisoryRecipients)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/alerts", wrapper.ListHOAlerts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/fa-alerts", wrapper.CreateHONote)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/fa/alerts", wrapper.ListFAAlerts)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/farmer/notices", wrapper.ListFarmerNotices)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/farmer/notices/unread-count", wrapper.GetUnreadNoticeCount)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/notices/{notice_id}/read", wrapper.MarkNoticeRead)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/notices/{notice_id}/listened", wrapper.MarkNoticeListened)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/web/notices/{notice_id}", wrapper.GetWebNotice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/web/notices/{notice_id}/listened", wrapper.MarkWebNoticeListened)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/hooks/sms/{provider}", wrapper.SmsDeliveryReport)
	})

	return r
}

