// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// SmsDeliveryReport SMS provider delivery report (STUB)
	// (POST /hooks/sms/{provider})
	SmsDeliveryReport(ctx context.Context, request SmsDeliveryReportRequestObject) (SmsDeliveryReportResponseObject, error)
	// ListAdvisories List advisories
	// (GET /v1/admin/advisories)
	ListAdvisories(ctx context.Context, request ListAdvisoriesRequestObject) (ListAdvisoriesResponseObject, error)
	// CreateAdvisory Create an advisory draft
	// (POST /v1/admin/advisories)
	CreateAdvisory(ctx context.Context, request CreateAdvisoryRequestObject) (CreateAdvisoryResponseObject, error)
	// PreviewAdvisoryRecipients Count the farmers a target would reach now
	// (POST /v1/admin/advisories/preview)
	PreviewAdvisoryRecipients(ctx context.Context, request PreviewAdvisoryRecipientsRequestObject) (PreviewAdvisoryRecipientsResponseObject, error)
	// GetAdvisory Get an advisory with its reach so far
	// (GET /v1/admin/advisories/{advisory_id})
	GetAdvisory(ctx context.Context, request GetAdvisoryRequestObject) (GetAdvisoryResponseObject, error)
	// UpdateAdvisory Edit a draft (including one Agronomy sent back)
	// (PATCH /v1/admin/advisories/{advisory_id})
	UpdateAdvisory(ctx context.Context, request UpdateAdvisoryRequestObject) (UpdateAdvisoryResponseObject, error)
	// ApproveAdvisory Approve an advisory that names a product (Agronomy)
	// (POST /v1/admin/advisories/{advisory_id}/approve)
	ApproveAdvisory(ctx context.Context, request ApproveAdvisoryRequestObject) (ApproveAdvisoryResponseObject, error)
	// CancelAdvisory Cancel an advisory before it starts sending
	// (POST /v1/admin/advisories/{advisory_id}/cancel)
	CancelAdvisory(ctx context.Context, request CancelAdvisoryRequestObject) (CancelAdvisoryResponseObject, error)
	// ListAdvisoryRecipients Farmers who received an advisory, with delivery status per channel
	// (GET /v1/admin/advisories/{advisory_id}/recipients)
	ListAdvisoryRecipients(ctx context.Context, request ListAdvisoryRecipientsRequestObject) (ListAdvisoryRecipientsResponseObject, error)
	// RejectAdvisory Send an advisory back to draft with a note (Agronomy)
	// (POST /v1/admin/advisories/{advisory_id}/reject)
	RejectAdvisory(ctx context.Context, request RejectAdvisoryRequestObject) (RejectAdvisoryResponseObject, error)
	// SubmitAdvisory Submit a draft to be sent now or at send_at
	// (POST /v1/admin/advisories/{advisory_id}/submit)
	SubmitAdvisory(ctx context.Context, request SubmitAdvisoryRequestObject) (SubmitAdvisoryResponseObject, error)
	// ListHOAlerts HO alerts for the overview (new farmers, farmers without an FA, FAs offline)
	// (GET /v1/admin/alerts)
	ListHOAlerts(ctx context.Context, request ListHOAlertsRequestObject) (ListHOAlertsResponseObject, error)
	// CreateHONote Send a note to an FA (shows in the FA app's Alerts tab)
	// (POST /v1/admin/fa-alerts)
	CreateHONote(ctx context.Context, request CreateHONoteRequestObject) (CreateHONoteResponseObject, error)
	// ListFAAlerts The FA's alerts, newest first
	// (GET /v1/fa/alerts)
	ListFAAlerts(ctx context.Context, request ListFAAlertsRequestObject) (ListFAAlertsResponseObject, error)
	// ListFarmerNotices My Crop Advisory inbox, newest first
	// (GET /v1/farmer/notices)
	ListFarmerNotices(ctx context.Context, request ListFarmerNoticesRequestObject) (ListFarmerNoticesResponseObject, error)
	// GetUnreadNoticeCount Number of unread notices (badge)
	// (GET /v1/farmer/notices/unread-count)
	GetUnreadNoticeCount(ctx context.Context, request GetUnreadNoticeCountRequestObject) (GetUnreadNoticeCountResponseObject, error)
	// MarkNoticeListened Record that the farmer played the voice note (idempotent; also marks read)
	// (POST /v1/farmer/notices/{notice_id}/listened)
	MarkNoticeListened(ctx context.Context, request MarkNoticeListenedRequestObject) (MarkNoticeListenedResponseObject, error)
	// MarkNoticeRead Mark a notice read (idempotent)
	// (POST /v1/farmer/notices/{notice_id}/read)
	MarkNoticeRead(ctx context.Context, request MarkNoticeReadRequestObject) (MarkNoticeReadResponseObject, error)
	// GetWebNotice A notice for the farmer web page opened from an SMS or WhatsApp link
	// (GET /v1/web/notices/{notice_id})
	GetWebNotice(ctx context.Context, request GetWebNoticeRequestObject) (GetWebNoticeResponseObject, error)
	// MarkWebNoticeListened Record a play of the voice note on the web page (idempotent)
	// (POST /v1/web/notices/{notice_id}/listened)
	MarkWebNoticeListened(ctx context.Context, request MarkWebNoticeListenedRequestObject) (MarkWebNoticeListenedResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

